function renderAccount(){page('account',shell('account',`<div class="account-box card"><div class="account-icon">◎</div><h3>Masuk ke ruang Anda</h3><p class="muted">Masuk untuk menyimpan aktivitas, mengikuti masalah, dan mengelola kontribusi.</p><div class="form"><label>Email<input id="loginEmail" type="email" placeholder="nama@email.com"></label><label>Password<input id="loginPassword" type="password" placeholder="••••••••"></label><button class="btn-primary" id="loginBtn">Masuk</button><div id="loginResult"></div></div></div>`));$('loginBtn').onclick=async()=>{const email=$('loginEmail').value.trim(),password=$('loginPassword').value;if(!email||!password){$('loginResult').innerHTML='<div class="notice danger">Email dan password wajib diisi.</div>';return}$('loginResult').innerHTML='<div class="notice">Memproses…</div>';try{const r=await fetch(`${SUPABASE_URL}/auth/v1/token?grant_type=password`,{method:'POST',headers:{apikey:SUPABASE_KEY,'Content-Type':'application/json'},body:JSON.stringify({email,password})});const d=await r.json();if(!r.ok)throw Error(d.error_description||d.msg||`HTTP ${r.status}`);localStorage.setItem('ipm_access_token',d.access_token||'');$('loginResult').innerHTML='<div class="notice success">Berhasil masuk.</div>'}catch(e){$('loginResult').innerHTML=`<div class="notice danger">${esc(e.message)}</div>`}}}
function renderMore(){page('more',shell('more',`<div class="list"><article><b>Tentang platform</b><small>Masalah Indonesia dilihat dari data dan pengalaman manusia.</small></article><article><b>Sumber & metodologi</b><small>Data produksi perlu provenance, waktu observasi, dan quality score.</small></article><article><b>Transparansi AI</b><small>Probability bukan kepastian dan rekomendasi dapat berubah.</small></article><article><b>Privasi & moderasi</b><small>Laporan warga adalah sinyal, bukan otomatis fakta atau tuduhan.</small></article></div>`))}
async function searchQuestion(q){page('result',`<div class="page"><span class="eyebrow">PENCARIAN INDONESIA</span><h2>“${esc(q)}”</h2><div id="searchResult" class="card"><div class="loading">Mencari wilayah, masalah, dan evidence…</div></div></div>`);try{const [a,b]=await Promise.allSettled([db(`/rest/v1/problems?select=id,title,category,status,confidence,impact_score&title=ilike.*${encodeURIComponent(q)}*&order=impact_score.desc.nullslast&limit=8`),db(`/rest/v1/regions?select=id,name,level,admin_code_pum,boundary_status&source_name=eq.BIG&name=ilike.*${encodeURIComponent(q)}*&limit=8`)]);const ps=a.status==='fulfilled'?a.value:[],rs=b.status==='fulfilled'?b.value:[];$('searchResult').innerHTML=(ps.length?`<div class="result-section"><b>Masalah terkait</b>${ps.map(x=>`<article class="issue-card"><div><b>${esc(x.title)}</b><small>${esc(x.category||'')} • ${esc(x.status||'')} • confidence ${esc(x.confidence??'—')}</small></div><strong>${x.impact_score==null?'—':Math.round(Number(x.impact_score))}</strong></article>`).join('')}</div>`:'')+(rs.length?`<div class="result-section"><b>Wilayah terkait</b>${rs.map(x=>`<article class="issue-card"><div><b>${esc(x.name)}</b><small>${esc(x.level)} • ${esc(x.admin_code_pum||'')}</small></div><button class="btn-outline" data-view="regions">Buka</button></article>`).join('')}</div>`:'')||'<div class="empty"><b>Belum ditemukan kecocokan langsung.</b><small>Coba nama wilayah atau masalah yang lebih spesifik.</small></div>';bind()}catch(e){$('searchResult').innerHTML=`<div class="notice danger">${esc(e.message)}</div>`}}
$('ask').onclick=()=>{const q=$('question').value.trim();if(q)searchQuestion(q)};$('question').onkeydown=e=>{if(e.key==='Enter')$('ask').click()};document.querySelectorAll('.topic-chips button').forEach(b=>b.onclick=()=>{$('question').value=b.dataset.q;$('ask').click()});$('mobileMenu').onclick=()=>$('mainNav').classList.toggle('open');$('headerSearch').onclick=()=>{scrollTo({top:0,behavior:'smooth'});$('question')?.focus()};bind();active('home');
(async()=>{try{const r=await fetch(`${SUPABASE_URL}/rest/v1/human_reports?select=id&limit=1`,{headers:{apikey:SUPABASE_KEY,Authorization:`Bearer ${SUPABASE_KEY}`,Prefer:'count=exact'}});const h=r.headers.get('content-range');const n=h?Number(h.split('/')[1]):null;if(n!=null&&$('liveReportCount'))$('liveReportCount').textContent=fmt(n)}catch{}})();